// ---------------------------------------------------------------------------
// Module 6 — Knowledge Centre (verbatim clauses from real HPCL circulars)
//
// The EAM clauses below (documentTitle "Empowerment & Authority Manual (EAM)
// Version 2.0 (dated 01/03/2024) — Chapter ...") are extracted verbatim from
// the real EAM v2.0 PDF (3 parts, ~58 pages) via pdfReader.ts, filtered to
// Chapters I/II/IV/V/VII (General, Sales, Finance, Capital Projects, Leases —
// the chapters actually relevant to a Retail Network Ops app) and, within
// Chapter II/IV/VII, to rows mentioning dealer/retail/outlet/resitement/
// lease/tax terms — Chapters III/VI/VIII-XIV (international trade, HR,
// mega projects, IS, PR, legal, R&D, digital) are out of this app's scope
// and were not indexed. Two other uploaded documents — a dealer subsidy
// circular and a letter re: eDFS — are genuinely scanned-image PDFs with no
// extractable text layer (no OCR service is reachable from this
// environment), so their content could not be added; ask the SO for a
// text-bearing version if that coverage is needed.
//
// The DSG clauses (documentTitle "Manual for Selection of Dealers for
// Regular & Rural Retail Outlets (Version 1.0, 10.06.2023) — Section N: ...")
// are extracted verbatim, one clause per numbered section (all 33, "1
// Identification of Locations" through "33 Estimated minimum fund..."), from
// the real 3-part DSG PDF via the same header-anchored parser approach —
// long sections are capped at ~3200 characters (a real excerpt, not a
// summary) rather than fabricating a shorter paraphrase. This replaces the
// two DSG "group classification" / "application fee" clauses that were
// written from general knowledge before a source PDF existed — the real
// application-fee figures turned out to match exactly, validating that
// clause, while the Resitement Policy PDF uploaded alongside these is (like
// the dealer subsidy circular) a scanned image with no extractable text, so
// the Resitement Guidelines clauses remain unverified pending a text-bearing
// copy.
// ---------------------------------------------------------------------------

