    heading: "Budget for computers/communication equipment’s to be concurred by Head-IS",
    text: "Budget for computers/communication equipment’s to be concurred by Head-IS. Appropriation of funds for new project office expenses INCLUDING for office furniture/equipment’s shall be met from the approved project cost only/AR. For appropriation of funds for Housing & Welfare equipment approvals will be required from: Head - Administration for Corporate/Marketing (Not below S/G ‘F’) Head - HR for Refinery (Not below S/G ‘F’)",
