    heading: "Any project over r 1 crore shall have an Internal…",
    text: "Any project over r 1 crore shall have an Internal Rate of Return (IRR) as decided by the CFD from time to time. CS&P shall advise the rate so fixed to all concerned. Until such time that the CFD first fixes the minimum IRR, the rate of 15% will apply. If any project does not fulfill the IRR criteria, then the project should have the approval of the Functional Director.",
