    documentTitle: "Empowerment & Authority Manual (EAM) Version 2.0 (dated 01/03/2024) — Chapter V — CAPITAL PROJECTS",
    clauseNumber: "5.3.f",
    heading: "Over r 10000 lakhs Board NOTE: The above limits are…",
    text: "Over r 10000 lakhs Board NOTE: The above limits are also applicable for : i) Cylinders, Regulators, Valves, Pumps, Signage’s etc. ii) Program Category Investment iii) In respect of projects requiring Board approval, CFD can authorize commitment/expenditure subject to max. 5% of project cost and not exceeding r 10 crores for pre project activities such as EIA study, site selection, route survey, detailed engineering excluding Land acquisition/site development 6 Unbudgeted items/change in scope for capital projects/ withdrawal from contingency. NOTE: - 1. Unbudgeted items/Capital Budget for supplementary appropriation shall be given only through savings arising out of executed projects or from projects under execution or from contingency provisions for Marketing/Refinery 2. Savings shall mean the uncommitted funds arising after the completion of a particular appropriation or uncommitted funds which will not be used for completion of balance part project. A declaration has to be furnished by the concerned user / department that commitments exceeding the revised amount shall not be made against the particular appropriation which is declared to be completed or expected to be completed with lower value. 3. Further, a notation shall be made by the user/department that the savings have not arisen because of substantial change in scope of the appropriation. Also, the project will be closed and the final AMCA (Asset Master Capitalization Advice) processed for capitalization of the same.",
