    text: "Purchase of land with or without super structures on existing outlets - Govt. Sites Executive Committee Marketing - Private Sites a. Where offer price is less than the Government guideline value obtained from revenue authorities and market valuation obtained from Government approved valuers Executive Committee Marketing b. Where offer price is more than the Govt. guideline value obtained from revenue authorities and less than market valuation obtained from Government approved valuers Board Sub Committee of Directors c. Where offer price is less than the Govt. guideline value obtained from revenue authorities and more than market valuation obtained from Government approved valuers Board Sub Committee of Directors",
