    documentTitle: "Empowerment & Authority Manual (EAM) Version 2.0 (dated 01/03/2024) — Chapter V — CAPITAL PROJECTS",
    clauseNumber: "7.1.c.iv",
    heading: "Appointment of Negotiating Team for purchase of existing Retail outlet…",
    text: "Appointment of Negotiating Team for purchase of existing Retail outlet sites/CNG outlets/Mother Station with or without super structures. SBU Head Note: 1. Rates are as obtained thru Public tender/advertisements. 2. Rates so obtained to be compared with market rates as approved by revenue Authorities. 3. Purchase of land shall be approved only after obtaining approval of capital projects 4. Where Executive Committee has approved purchase of Govt. land, the payment of installments can be made by paying authority without referring to Executive Comm. Provided total cost is within 10% of originally approved amount. 5. Purchase of land in 'A', ‘B’ and ‘D’ class of markets for developments of new Retail Outlet Dealership, Pipeline Stations/Anode Bed/CNG outlet/Mother Station, Refinery would be referred to Contracts/Executive Comm./ CFD depending upon the value of land. 6. While negotiating with land lords, the following shall be considered: a the actual land transactions (purchase/sale) in the area during last six months, if any b. whether any acquisition proceedings have been initiated/are proposed to be initiated by the local authorities/bodies c. the trend in the real estate value in the area Note Nos.1, 2 & 3 are applicable to Clauses 7.1.a, b & c Note No.4 is applicable to Clauses 7.1.b and 7.1.c.2 Note No.5 is applicable to Clause 7.1.a & 7.1.c",
