    heading: "Rostering of locations and Type of RO sites",
    text: "eparate Roster (State Retail Marketing Plan) Regular ROs and Rural ROs should have separate rosters (SRMPs) duly approved by Retail head of State/Zonal/State office. B. Allocation of location under different categories & completion of Roster Locations finalized for setting up of Retail Outlets are to be placed under different categories of reservation as per the slot allocated to each category under the ‘200 point’ roster (Annexure - B1) for each State by the oil company so as to ensure the percentage reservation for each category is achieved. In the ‘200-point’ Roster, the allocation of a reserved category against a serial number is done in such a way that when 200 numbers of Retail Outlets are planned in a state by an oil company, the percentage of reservation for each category is achieved. Previous roster(s) prepared during 2018 to be treated as closed and fresh roster to be prepared and calculation of backlog numbers as given in the Para C below. Annexure - C State-wise Allotment of Roster number between SC and ST Sr. No. State / Union Territory % of SC/ST w.r.t. Total SC & ST (based on Census 2011) Total SC/ST bifurcation out of 45 Roster Sr. No. for SC ST SC ST SC ST 1 Andaman & Nicobar 0 100 0 45 NIL ALL 2 Andhra Pradesh 70 30 32 13 All Except 7, 29, 43, 65, 74, 83, 100, 114, 132, 149, 154,167, 189. 7, 29, 43, 65, 74, 83, 100, 114, 132, 149, 154,167, 189. 3 Assam 36 64 16 29 7, 20, 38, 47, 65, 74, 83, 96, 109, 118, 136, 149, 154, 167, 185, 194. All Except 7, 20, 38, 47, 65, 74, 83, 96, 109, 118, 136, 149, 154, 167, 185, 194. 4 Bihar 93 7 42 3 All Except 47, 132, 140. 47, 132, 140. 5 Chandigarh 100 0 45 0 ALL NIL 6 Chattisgarh 30 70 13 32 12, 20, 56, 69, 74, 87, 100, 127, 140, 158, 180, 189, 194 All Except 12, 20, 56, 69, 74, 87, 100, 127, 140, 158, 180, 189, 194 7 Dadra & Nagar Haveli 3 97 2 43 92, 176 All Except 92, 176 8 Daman & Diu 29 71 13 32 12, 20, 56, 69, 74, 87, 100, 127, 140, 158, 180, 189, 194 All Except 12, 20, 56, 69, 74, 87, 100, 127, 140, 158, 180, 189, 194 9 Delhi 100 0 45 0 ALL NIL 10 Goa 15 85 7 38 12, 34, 60, 96, 132, 149, 180 All Except 12, 34, 60, 96, 132, 149, 180 11 Gujarat 31 69 14 31 3, 12, 25, 34, 51, 60, 78, 96, 114, 132, 149, 163, 180, 198 All Except 3, 12, 25, 34, 51, 60, 78, 96, 114, 132, 149, 163, 180, 198 12 Haryana 100 0 45 0 ALL NIL Rostering of the identified locations will start afresh from Sr. No. 1. Once the roster serial number is completed at 200, the next round of roster serial number will start again from no. 1 for the state. Locations finalized for setting up of Retail outlets in North Eastern States as mentioned in the reservation table for the States of Arunachal Pradesh, Meghalaya, Nagaland and Mizoram should be placed under different categories of reservation as per ‘100 point’ roster as given in Annexure - B2. In the ‘100-point Roster’, allocation of a reservation category against a serial number should be done such that when 100 numbers of RO dealerships are planned, the percentage of each category (of reservation) is achieved. Once the 100 roster serial numbers are completed, the next round of roster serial number will start again from no. 1 for the state. The locations would be …",
