    heading: "Direct Award of Dealership",
    text: "ovt. agencies / Departments / PSUs can be considered for award of dealerships directly without advertisement in addition to their eligibility to apply under OPEN category. The shareholding of the government in such government agencies /PSUs should be minimum 50%. In addition, Policies approved by OMCs for direct allotment of dealerships under Corporate tie ups as advised by MOP&NG vide letter No. P-38012/3/2008-IOC (Pt.) dated 15.9.2008 and to the successful bidders of WSA (Way Side Amenities) as per the MOP&NG letter M-12043 (11)/69/2021-OMC-PNG Dated 13.08.2021 would continue.",
