    id: "POL-DSG-S12",
    documentTitle: "Manual for Selection of Dealers for Regular & Rural Retail Outlets (Version 1.0, 10.06.2023) — Section 12: Basic facilities required for operation of RO dealership",
    clauseNumber: "Section 12",
    heading: "Basic facilities required for operation of RO dealership",
    text: "he following facilities are required to be provided at the retail outlet as specified by the OMC. Depending upon on the type of site the facilities are to be made available by the Dealer (as specified by the OMC) / OMC as mentioned against each type of facility: Screen Shot 15 Appendix - IIB Notarized Affidavit from Spouse of LOI holder in case she / he wishes/does not wish to become a partner (TO BE TYPED ON APPROPRIATE NON-JUDICIAL STAMP PAPER OF REQUIRED VALUE) (To be submitted by Spouse of the individual LOI (Letter of Intent) holder before acceptance of Letter of Appointment / Signing of Dealership Agreement) In the matter of RO dealership of Indian Oil Corporation Ltd.* / Bharat Petroleum Corporation Ltd.* / Hindustan Petroleum Corporation Ltd.* at___________ (Location) District_________ under_________ category Advertised on ___________. I, _____________________________son / daughter / wife of ________________________________ Age _____ years resident of _________ do hereby solemnly declare: 1. That my husband / wife Shri/Smt. ___________________, has applied for the above RO dealership and _______________ (OMC name) has issued Letter of Intent vide letter ref no ___________ dated ____________ in favour of my husband / wife. 2. That I am aware, that as per Terms and Conditions of the Dealer Selection, I have to be inducted as co-owner i.e., 50% partner of RO dealership allotted to my husband / wife Shri/Smt. ___________________. *I wish to become a partner/co-owner in the dealership allotted to my husband / wife Shri / Smt. ____________. I also undertake that all necessary documentation and undertaking / affidavit as required for award of dealership will be completed by me prior to issuance of Letter of Appointment (LOA). OR *That I am currently gainfully employed as mentioned below:- Details of employment with Employer’s address. Hence, I do not wish to be made a partner in the Dealership allotted to my husband / wife Shri/Smt. ___________________. OR *That I do not wish to be made a partner in the Dealership allotted to my husband / wife Shri/Smt. ___________________ for personal reasons. *Strike off whichever is not applicable. Solemnly affirmed and declared before me This ___________day of ________________ Signature and Seal of Signature Magistrate/Judge/Notary Public Name of Deponent Note: The stamp paper should be purchased in the name of the deponent A. Site specific additional facilities required for customer service such as Staff cum Change Room, Service Station, Rest Room, Restaurant, PUC facility and/other Facilities as may be specified by Oil Company from time to time will be provided by Oil Company/Dealer Select as applicable. B. Firefighting & Safety Equipment Dealer will provide Firefighting/Safety equipment at Retail Outlet as per the statutory requirements and maintain them in good working condition at his/her own cost. Trained staff should be available to handle and operate the same. C. Investment Required: The approximate investments required for the development of infrastructure and facilities & working capital requirement at New Retail Outlets will be indicated in the advertisement. The selected candidate shall …",
