    documentTitle: "Manual for Selection of Dealers for Regular & Rural Retail Outlets (Version 1.0, 10.06.2023) — Section 15: Affidavit",
    clauseNumber: "Section 15",
    heading: "Affidavit",
    text: "he applicants should submit an affidavit in the standard format confirming facts as per Appendix – XA (for individual) and APPENDIX - XB (for Non-individual). Note: 1. All affidavits should be submitted in original on stamp paper of appropriate value as applicable in the concerned State. 2. All Stamp papers should be purchased in the name of the deponent. 3. All affidavits should be made after the date of advertisement. 176 Appendix – XA Notarized Affidavit (TO BE TYPED ON APPROPRIATE NON-JUDICIAL STAMP PAPER OF REQUIRED VALUE) (To be submitted by individual applicants) I,____________________________________ son/daughter/wife of ______________________________ Age _____ years residing at __________________________ . In connection with my application for RO dealership at ____________(Location) _____________(Dist.) _____________(State) I do hereby solemnly affirm and say as under : 1 That I am an Indian Citizen and resident of India (as per Income Tax Rules1) 2 That my date of birth is d d / m m / y Y y y 3 That I have passed the Matriculation / 10th Std. Examination conducted by Board in the year / Certificate issued by Armed Forces as equivalent to 10th Class pass in the year y y y y 4 That I hereby confirm that I am eligible for allotment of Retail Outlet dealership as per applicability of Multiple Dealership Norm defined under Clause “Disqualification” in the “ Brochure for Selection of Dealers for Regular & Rural Retail Outlets” and do not disqualify for allotment of Retail Outlet dealership under other conditions mentioned therein. 5 That I hereby confirm that none of my family members (as defined under Clause “DISQUALIFICATION” of brochure) are employees of Indian Oil Corporation Ltd., Bharat Petroleum Corporation Ltd. and Hindustan Petroleum Corporation Ltd. 6(a) That I am Unmarried Or That I am Married and the name of my spouse is Shri/Smt._______________ 6(b) My name before my marriage was _______________ and after my marriage to Shri ___________ my name has been changed to Smt. ___________________. (only for female applicants, wherever applicable) 6(c) That my name earlier was Shri/Smt./Kum ___________________ and has been changed to Shri/Smt./Kum ___________________ w.e.f. ________________ (Applicable in case of name change by applicant) 7 That, I am of sound mental health & I am not totally paralyzed. 8 That I have never been convicted for any criminal offence involving moral turpitude and/or economic offences (other than freedom struggle). 9 I confirm that arrangement will be made for taking delivery of products on ex-MI basis from the Oil Company within 4 months of intimation thereof from the Oil Company to this effect. 10 I hereby confirm that neither I nor any member of my “family unit” (as defined under Multiple dealership norm for individuals/non-individuals of Disqualification criteria), was ever a signatory to dealership/distributorship agreement of any Oil Company, which was terminated for proven malpractices and / or for violations of provisions of the Marketing Discipline Guidelines 11 In case I am selected for RO dealership, I undertake to develop the desired infrastructure and facilities at the Outlet allotted as per …",
    tags: ["dsg", "dealer", "retail", "disqualification", "affidavit", "selection", "spouse"],
