    id: "POL-DSG-S20",
    documentTitle: "Manual for Selection of Dealers for Regular & Rural Retail Outlets (Version 1.0, 10.06.2023) — Section 20: Information update on web site",
    clauseNumber: "Section 20",
    heading: "Information update on web site",
    text: "www.petrolpumpdealerchayan.in) The following information in respect of Various Stages of Selection process for a location will be available in the website. Observation on scrutiny of rectifiable documents submitted by the applicant: (wherever applicable) Rectifiable deficiency Document submitted / not submitted Observation (document found Ok or not) a. b. c. CANDIDATE IS: ELIGIBLE / INELIGIBLE / TO BE CONSIDERED UNDER GROUP-3 Signature with date Member - I Signature with date Member - II Name & Designation Name & Designation Signature of Officer at Division / Territory / Regional Office Name & Designation Signature of Divisional / Territory / Regional Office in-charge Name & Designation Annexure – W2 Layout Sketch of land offered by the applicant 1. Advertised Location: 2. Regular / Rural: 3. Sr. No. As Per Advertisement: 4. Category: 5. Offered Land Details: a. Land (Plot) No.: (Khasara/Khatauni/Patta/Dag/Gatta/Gut/Survey/Plot no. etc.) b. Revenue Village: c. Tehsil: d. Disctrict: e. State: f. Name / No. Of The Road Abutting The Offered Plot: (NH/SH/MDR/ODR/Road no. or name of road) 6. Name Of Applicant: I hereby confirm that the above mentioned details of the land offered by me are correct and the plot of land which has been inspected by the Company Officials on __________ which is more specifically indicated in the sketch / layout below, is the same plot of land which has been offered by me in my application for development of retail outlet at the location mentioned above. Further, I also confirm that:- i. The plot of land offered by me meets the minimum advertised dimension / area, after leaving Right of Way (ROW) line of the road and is situated abutting the ROW of the road. ii. The offered plot of land is not notified for acquisition. iii. I / The Land owner(s) am/is/are in Possession of the land from the beginning / edge of ROW line. iv. There is no other land (including Govt. land) between ROW and offered plot. I also understand that in case any of the details mentioned above are found incorrect or the site is found unsuitable by the Corporation for any reason whatsoever then I would have no claim on the dealership of this location. (i) Advertisement - Name of newspaper, date, cutoff date, name and details of location including category of location – As per Annexure - H1 and Annexure - H2. (ii) Location wise no of applications received along with name of applicants under Group - 1, Group - 2 & Group - 3 and their status w.r.t selection– As per Annexure - O2 (iii) Details of Affidavits, submitted by the provisionally selected candidate as per Appendix - IV stating that he/she is not employed in Private Sector or is not drawing any salary/perks/emoluments from State / Central Government – Annexure - X.",
    tags: ["dsg", "dealer", "retail", "affidavit", "selection"],
