    heading: "False Information",
    text: "f any statement made in the application or in the documents uploaded/ submitted or subsequently uploaded/ submitted in pursuance of the application by the candidate at any stage is found to have been suppressed / misrepresented / incorrect or false, then the application is liable to be rejected without assigning any reason and in case, the applicant has been appointed as a dealer, the dealership is liable to be terminated. In such cases the candidate / dealer shall have no claim whatsoever against the respective Oil Company.",
